class Solution {
public:
 int earliestFinishTime(vector<int>& landStartTime,vector<int>& landDuration,vector<int>& waterStartTime,vector<int>& waterDuration){
  int ans=INT_MAX;for(int i=0;i<(int)landStartTime.size();++i)for(int j=0;j<(int)waterStartTime.size();++j){
   ans=min(ans,max(landStartTime[i]+landDuration[i],waterStartTime[j])+waterDuration[j]);
   ans=min(ans,max(waterStartTime[j]+waterDuration[j],landStartTime[i])+landDuration[i]);}return ans;
 }
};
